-- Food Conscious PostgreSQL Schema & Seed Data
-- Compatible with Neon, Supabase, Render Postgres, etc.

CREATE TABLE IF NOT EXISTS users (
    userid SERIAL PRIMARY KEY,
    username VARCHAR(255) UNIQUE NOT NULL,
    password VARCHAR(255) NOT NULL
);

CREATE TABLE IF NOT EXISTS recipe (
    recipeid SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    userid INTEGER
);

CREATE TABLE IF NOT EXISTS fooddata (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    energykj INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS ingredients (
    ingredientid SERIAL PRIMARY KEY,
    userid INTEGER,
    recipeid INTEGER,
    dataid INTEGER,
    ingredientname VARCHAR(255),
    kj100 INTEGER,
    quantity NUMERIC,
    kj INTEGER,
    custom VARCHAR(10)
);

CREATE TABLE IF NOT EXISTS fooddiary (
    logid SERIAL PRIMARY KEY,
    userid INTEGER,
    food VARCHAR(255),
    meal VARCHAR(50),
    kjenergy INTEGER,
    date DATE DEFAULT CURRENT_DATE
);

-- Seed Food Data
SELECT setval(pg_get_serial_sequence('fooddata', 'id'), COALESCE((SELECT MAX(id) FROM fooddata), 1));
